using System.Collections.Generic;
using Rapadura.Core.Localization;
using static Rapadura.Gameplay.Quests.LateStoryTexts;

namespace Rapadura.Gameplay.Quests
{
    /// <summary>
    /// Localization (en + pt-BR) of "A Lua que Não Enche" (<see cref="MidStoryCatalog"/>, Docs/HistoriaMeio_20a100.md), in the shape of the letters: per step the title, the
    /// description, the objectives, the journal (Vó Edna on the radio), the progress line and one offer per cousin (Joaquim, Maria, Maithe, Ícaro, Lavine); and one "too low"
    /// line per cousin for the whole chain. Keys <c>quest.mid_story_*</c>; added to <see cref="LateStoryTexts.All"/>, so <c>CityQuestTexts</c> carries them.
    /// </summary>
    public static class MidStoryTexts
    {
        public static void AddTo(List<LocalizationEntry> all)
        {
            // ================= Região 4, Grutas do Limiar: o fim da campanha =================
            Step(all, "mid_story_r04_moon",
                T("The Moon That Won't Fill", "A Lua que Não Enche"),
                T("Since the seal was remade, every freed spark should be climbing to the Moon Ship, and the moon should grow night after night. Grandma Edna has watched it from the iwan for a week: it stays a fingernail. Grandpa Jorge used to say that whoever lives by the seal knows where the light goes. Tages lives by the seal.",
                  "Desde que o selo foi refeito, toda faísca libertada devia subir para a Barca da Lua, e a lua devia crescer noite após noite. A Vó Edna olha do iwan há uma semana: ela continua uma unha. O Vô Jorge dizia que quem mora perto do selo sabe para onde a luz vai. O Tages mora perto do selo."),
                T("Reach Tages's hall, at the bottom of the Grutas", "Chegar ao salão do Tages, no fundo das Grutas"),
                null,
                T("Tages borrowed a lamp and then told us: the sparks we free go up, but out on the far roads there are beasts still hungry with the old hunger of Āz, and they snatch the light on its way to the Moon. He named four places close by. Grandma Edna wrote them in the Caderno and said the moon can wait for us to eat first.",
                  "O Tages pediu uma lamparina emprestada e depois contou: as faíscas que a gente solta sobem, mas nas estradas de longe ainda tem bicho com a fome velha da Āz, e eles pegam a luz no caminho para a Lua. Ele disse quatro lugares aqui perto. A Vó Edna escreveu no Caderno e disse que a lua pode esperar a gente comer primeiro."),
                T("Tages is afraid of the dark, not of you. Go down with a lamp lit and ask him kindly.",
                  "O Tages tem medo do escuro, não de vocês. Desce com a lamparina acesa e pergunta com jeito."),
                T("Joaquim, eat that plate and then go down to the Grutas. Tages knows why the moon won't fill. Leave the shield at the door of his hall; he jumps at loud things.",
                  "Joaquim, come esse prato e depois desce para as Grutas. O Tages sabe por que a lua não enche. Deixa o escudo na porta do salão dele; ele se assusta com barulho."),
                T("Maria, my light, you were the one who lit him up slowly the first time. He trusts you. Ask him where the sparks are going, because they are not reaching the Moon.",
                  "Maria, minha luz, foi você quem acendeu ele devagarinho da primeira vez. Ele confia em você. Pergunta para onde as faíscas estão indo, porque na Lua elas não chegam."),
                T("Maithe, my eldest, count the moon with me: one week, and it hasn't grown a hair. Your eye sees what hides. Go and see what Tages sees from down there.",
                  "Maithe, minha mais velha, conta a lua comigo: uma semana, e não cresceu um fio. O teu olho vê o que se esconde. Vai ver o que o Tages vê lá de baixo."),
                T("Ícaro, your light meter says the sparks go up, and my eyes say the moon stays thin. One of the two is wrong, and I'm too old to be wrong. Take the meter to Tages.",
                  "Ícaro, o teu medidor diz que as faíscas sobem, e os meus olhos dizem que a lua continua fina. Um dos dois está errado, e eu estou velha demais para errar. Leva o medidor até o Tages."),
                T("Lavine, my youngest, he still keeps the soft shadow you showed him. He'll talk to you before anyone. Take him a lamp, and ask him about the moon.",
                  "Lavine, minha caçula, ele ainda guarda a sombra macia que você mostrou. Ele fala com você antes de todo mundo. Leva uma lamparina para ele e pergunta da lua."));
            all.Add(new LocalizationEntry("quest.mid_story_r04_moon.obj_" + MidStoryCatalog.SealObjectiveId, "Remake the seal of the Grutas with Tages", "Refazer o selo das Grutas com o Tages"));

            // ================= O segundo anel das Regiões 1–4 =================
            Step(all, "mid_story_r01_garden",
                T("Sparks in the Garden", "Faíscas no Jardim"),
                T("The first place Tages named is the garden of Mihrshah, past the canopy of Garajonay. Gara has seen it from the bridges at night: little lights going up and stopping halfway, caught in the moss of stone golems.",
                  "O primeiro lugar que o Tages disse é o jardim de Mihrshah, depois das copas de Garajonay. A Gara viu das pontes, de noite: luzinhas subindo e parando no meio, presas no musgo dos golens de pedra."),
                T("Reach the garden of Mihrshah", "Chegar ao jardim de Mihrshah"),
                T("Free the stone golems that hold the sparks", "Libertar os golens de pedra que seguram as faíscas"),
                T("Six golems, six little lights let go. Grandma Edna says the moon got one hair thicker last night, and that she checked it twice. She told us Namrael's throne is next and that the sands there bite: Gara sent a theriac along.",
                  "Seis golens, seis luzinhas soltas. A Vó Edna diz que a lua engordou um fio ontem à noite, e que conferiu duas vezes. Disse que o próximo é o trono do Namrael e que a areia lá morde: a Gara mandou uma teriaga junto."),
                T("The golems sit still and hold on. Make them let go, one by one.",
                  "Os golens ficam parados e seguram. Façam eles soltarem, um por um."),
                T("Joaquim, the golems in the garden are bigger than you, and slower. Stand in front, then step aside when they swing. Your grandmother told me you learned that in the Serra.",
                  "Joaquim, os golens do jardim são maiores que você, e mais lentos. Fica na frente e sai da frente quando eles balançarem. A tua avó me contou que você aprendeu isso na Serra."),
                T("Maria, the laurels lean towards you, and the sparks would too, if the golems let them. Six of them. Go with light, and come back across the bridge before the mist.",
                  "Maria, os louros se inclinam para você, e as faíscas também iam, se os golens deixassem. Seis deles. Vai com luz e volta pela ponte antes da névoa."),
                T("Maithe, from my bridges you can count the stuck lights. I counted six, you will count seven, and you'll be right. Free them all.",
                  "Maithe, das minhas pontes dá para contar as luzes presas. Eu contei seis, você vai contar sete e vai estar certa. Solta todas."),
                T("Ícaro, the moss on those golems is warm. Warm moss on cold stone. Write that down, and then knock six of them loose.",
                  "Ícaro, o musgo desses golens é morno. Musgo morno em pedra fria. Anota isso e depois derruba seis deles."),
                T("Lavine, up here nobody is small, because everyone is far from the ground. The garden is at the end of the bridges. Six golems, and keep the red ribbon tied.",
                  "Lavine, aqui em cima ninguém é pequeno, porque todo mundo está longe do chão. O jardim fica no fim das pontes. Seis golens, e deixa a fita vermelha amarrada."));

            Step(all, "mid_story_r02_throne",
                T("The Salt Throne", "O Trono de Sal"),
                T("Grandpa Jorge crossed the Areias with the caravans, and Ashmunikal still beats the drum he liked. She says the broken lanterns around Namrael's salt throne have started drinking light that isn't theirs.",
                  "O Vô Jorge atravessou as Areias com as caravanas, e a Ashmunikal ainda toca o tambor de que ele gostava. Ela diz que as lanternas quebradas em volta do trono de sal do Namrael começaram a beber luz que não é delas."),
                T("Reach Namrael's throne", "Chegar ao trono do Namrael"),
                T("Free the broken lanterns that drink the sparks", "Libertar as lanternas quebradas que bebem as faíscas"),
                T("The lanterns went dark one by one and the sparks went up like sparks off the tandir. Grandma Edna laughed on the radio and said Jorge once tried to fix one of those lanterns with chewing gum. She says the Serra is next, and it is cold: drink the ginger tea.",
                  "As lanternas foram apagando uma por uma e as faíscas subiram que nem fagulha do tandir. A Vó Edna riu pelo rádio e disse que o Jorge uma vez tentou consertar uma dessas lanternas com chiclete. Disse que a Serra é a próxima e que lá faz frio: bebam o chá de gengibre."),
                T("A lantern that drinks light is still a lantern. Empty them and they'll remember.",
                  "Lanterna que bebe luz continua lanterna. Esvaziem, que elas lembram."),
                T("Joaquim, your arms don't shake, so hold the drum of your courage steady too. Six lanterns at the throne, and the salt there cuts the feet. Boots on.",
                  "Joaquim, os teus braços não tremem, então segura firme o tambor da coragem também. Seis lanternas no trono, e o sal lá corta os pés. Bota nos pés."),
                T("Maria, my tower lamp and your light are cousins. Those lanterns are cousins gone sour. Six of them. Show them what a lamp is for.",
                  "Maria, a lâmpada da minha torre e a tua luz são primas. Aquelas lanternas são primas azedas. Seis delas. Mostra para elas para que serve uma lâmpada."),
                T("Maithe, the wind around the throne carries salt into your eye. Shoot with the wind at your back, six times, and don't let your brother stand in front.",
                  "Maithe, o vento em volta do trono joga sal no olho. Atira com o vento nas costas, seis vezes, e não deixa o teu irmão ficar na frente."),
                T("Ícaro, the Artífices made those lanterns, I'm told. Made things can be unmade and made again. Take six apart for me, gently, and keep one screw.",
                  "Ícaro, me contaram que foram os Artífices que fizeram essas lanternas. Coisa feita pode ser desfeita e feita de novo. Desmonta seis para mim, com jeito, e guarda um parafuso."),
                T("Lavine, the drum says go when it beats twice. Listen: two. The throne is south, past the dunes, and the lanterns are afraid of soft shadows. You have one.",
                  "Lavine, o tambor diz vai quando bate duas vezes. Escuta: duas. O trono fica ao sul, depois das dunas, e as lanternas têm medo de sombra macia. Você tem uma."));

            Step(all, "mid_story_r03_summit",
                T("Mist on the Summit", "Névoa no Cume"),
                T("Napirasu keeps the fire of the Grande Forja and swears it has been hungry since the seal. At the summit of the Mazans the Ill Wind's mist wraps itself around every spark that rises from the Serra and keeps it.",
                  "A Napirasu cuida do fogo da Grande Forja e jura que ele anda com fome desde o selo. No cume dos Mazans, a névoa do Vento Ruim se enrola em toda faísca que sobe da Serra e fica com ela."),
                T("Reach the summit of the Mazans", "Chegar ao cume dos Mazans"),
                T("Free the mists of the Ill Wind", "Libertar as névoas do Vento Ruim"),
                T("Once the mist let go, Ícaro's meter jumped and Maithe's eye cleared. Grandma Edna says she could see a quarter moon from the iwan, the first in a long while, and she called Ari over to look. Napirasu sent a flask of eternal-fire oil: the deep tunnels are dark.",
                  "Quando a névoa soltou, o medidor do Ícaro pulou e o olho da Maithe clareou. A Vó Edna diz que viu um quarto de lua do iwan, o primeiro em muito tempo, e chamou o Ari para olhar. A Napirasu mandou um frasco de óleo do fogo eterno: os túneis de baixo são escuros."),
                T("The mist lies to the eye. Trust the cousin beside you.",
                  "A névoa mente para o olho. Confiem no primo do lado."),
                T("Joaquim, you stand like a pillar. Up on the summit the wind pushes pillars. Lean into it, free six mists, and come back for soup.",
                  "Joaquim, você fica parado feito pilar. Lá no cume o vento empurra pilar. Inclina contra ele, solta seis névoas e volta para a sopa."),
                T("Maria, you felt the crystal of the Forja once. It's asleep and hungry now. The sparks it wants are up on the summit, inside the mist. Six mists, and bring the light down.",
                  "Maria, você já sentiu o cristal da Forja. Agora ele está dormindo e com fome. As faíscas que ele quer estão lá no cume, dentro da névoa. Seis névoas, e traz a luz para baixo."),
                T("Maithe, I know what that mist did to your eye last time. It will try again. This time, let your cousins count for you. Six, and you only have to shoot.",
                  "Maithe, eu sei o que aquela névoa fez com o teu olho da outra vez. Ela vai tentar de novo. Desta vez, deixa os primos contarem por você. Seis, e você só precisa atirar."),
                T("Ícaro, the mist on the Mazans has a temperature, a speed and a smell. Measure all three and then blow six of them apart. A dwarf asks for numbers, not stories.",
                  "Ícaro, a névoa dos Mazans tem temperatura, velocidade e cheiro. Mede os três e depois desmancha seis delas. Anã pede número, não história."),
                T("Lavine, the Ill Wind is loud and cold. You are quiet and warm. That is a fight you win. Six mists at the summit, and wrap up before you go.",
                  "Lavine, o Vento Ruim é barulhento e frio. Você é quieta e quente. Essa briga você ganha. Seis névoas no cume, e se agasalha antes de ir."));

            Step(all, "mid_story_r04_aqueducts",
                T("The Deep Aqueducts", "Os Aquedutos Profundos"),
                T("Takhsich has been measuring the air of the Mercado dos Túneis since the seal. The fans turn, the air moves, and still something below the Canyon of the Wheel drinks the light: lantern fish in the deep aqueducts, glowing with sparks they swallowed.",
                  "O Takhsich mede o ar do Mercado dos Túneis desde o selo. Os cata-ventos giram, o ar anda, e mesmo assim alguma coisa debaixo do Cânion da Roda bebe a luz: peixes-lanterna nos aquedutos profundos, brilhando com faíscas que engoliram."),
                T("Reach the deep aqueducts of the canyon", "Chegar aos aquedutos profundos do cânion"),
                T("Free the lantern fish that swallowed the sparks", "Libertar os peixes-lanterna que engoliram as faíscas"),
                T("The fish spat out the light and swam off. The water of the aqueducts runs to the sea, Takhsich says, and so did some of the sparks: down to the coast of the monsoons. Grandma Edna sighed on the radio and said she always knew the moon would make us travel. He paid our passage on a dhow.",
                  "Os peixes cuspiram a luz e foram embora. A água dos aquedutos corre para o mar, diz o Takhsich, e parte das faíscas também: até a costa das monções. A Vó Edna suspirou pelo rádio e disse que sempre soube que a lua ia fazer a gente viajar. Ele pagou a nossa passagem num dhow."),
                T("Follow the glow in the water. The fish are the ones that shine too brightly.",
                  "Sigam o brilho na água. Os peixes são os que brilham demais."),
                T("Joaquim, stand there. No, there, in the canal. The fish come to whatever blocks the water, and you block water very well. Six of them, for science.",
                  "Joaquim, fica ali. Não, ali, no canal. Os peixes vêm para o que segura a água, e você segura água muito bem. Seis deles, pela ciência."),
                T("Maria, those fish shine with stolen light, and it hurts them. A healer would see it at once. Six fish, and the light goes back up where it belongs.",
                  "Maria, esses peixes brilham com luz roubada, e isso dói neles. Uma curandeira vê na hora. Seis peixes, e a luz volta para cima, que é o lugar dela."),
                T("Maithe, down in the aqueducts the echo makes two of everything. Count, then halve. Six fish, which will look like twelve.",
                  "Maithe, lá nos aquedutos o eco faz dois de tudo. Conta e divide por dois. Seis peixes, que vão parecer doze."),
                T("Ícaro! At last someone who will read my gauges. The deep aqueducts dropped four marks of light this week. Six lantern fish should bring them back. Note the readings before and after.",
                  "Ícaro! Finalmente alguém que vai ler os meus medidores. Os aquedutos profundos caíram quatro marcas de luz esta semana. Seis peixes-lanterna devem trazer de volta. Anota o antes e o depois."),
                T("Lavine, the fish are afraid of the dark, like Tages was. Your shadow is the soft kind. Go first, and they will let go of the light without a fight. Mostly.",
                  "Lavine, os peixes têm medo do escuro, que nem o Tages tinha. A tua sombra é da macia. Vai na frente que eles soltam a luz sem briga. Quase sempre."));

            // ================= Região 5, Costa das Monções =================
            Step(all, "mid_story_r05_gulls",
                T("Thieves on the Beach", "Ladrões na Praia"),
                T("The dhow left the cousins at Taa Pwani. From the coral lighthouse, Nuru has watched little lights fall into the sea with the rain of the monsoon, and thief gulls dive for them as if they were fish.",
                  "O dhow deixou os primos em Taa Pwani. Do farol de coral, a Nuru vê luzinhas caindo no mar junto com a chuva da monção, e gaivotas ladras mergulham atrás delas como se fossem peixe."),
                T("Reach the beach of the dhows", "Chegar à praia dos dhows"),
                T("Free the thief gulls that steal the sparks", "Libertar as gaivotas ladras que roubam as faíscas"),
                T("Seven gulls, and every one of them had a spark in its beak. Grandma Edna says the moon has a belly now, a small one. She asked whether we've been eating, and Joaquim answered before anyone could lie. Nuru gave us a breathing shell for the deep water.",
                  "Sete gaivotas, e cada uma tinha uma faísca no bico. A Vó Edna diz que a lua agora tem barriga, uma pequena. Perguntou se a gente está comendo, e o Joaquim respondeu antes que alguém pudesse mentir. A Nuru deu uma concha de respirar para a água funda."),
                T("The gulls go for whatever shines. Hold your light low.",
                  "As gaivotas vão em tudo que brilha. Segurem a luz baixa."),
                T("Joaquim, you stand before your cousins the way my tower stands before the sea. The gulls come at towers. Let them come at you, and free seven.",
                  "Joaquim, você fica na frente dos primos do jeito que a minha torre fica na frente do mar. As gaivotas atacam torre. Deixa elas atacarem você, e solta sete."),
                T("Maria, we are almost namesakes, you and I. A light shouldn't end in a gull's beak. Seven of them on the beach of the dhows. Go and give the light back to the sky.",
                  "Maria, nós somos quase xarás, você e eu. Luz não devia acabar em bico de gaivota. Sete delas na praia dos dhows. Vai devolver a luz para o céu."),
                T("Maithe, gulls fly in loops, and loops can be counted. Seven loops, seven arrows. Mind the wind off the sea, it turns at noon.",
                  "Maithe, gaivota voa em volta, e volta dá para contar. Sete voltas, sete flechas. Cuidado com o vento do mar, ele vira ao meio-dia."),
                T("Ícaro, the gulls are stealing what your meter counts. Seven thieves on my beach. Catch them before your numbers fly off.",
                  "Ícaro, as gaivotas estão roubando o que o teu medidor conta. Sete ladras na minha praia. Pega elas antes que os teus números voem."),
                T("Lavine, they stole a sailor's hat yesterday and a fisherman's lunch the day before. Today they steal light. Seven gulls. They will not steal from you.",
                  "Lavine, elas roubaram o chapéu de um marinheiro ontem e o almoço de um pescador anteontem. Hoje roubam luz. Sete gaivotas. De você elas não roubam."));

            Step(all, "mid_story_r05_baobabs",
                T("The Hollow Baobabs", "Os Baobás Ocos"),
                T("Ensuhkeshdanna of Aratta loves a riddle: what hides in a tree that is wider than it is tall? Baboons, and the sparks they hoard in the hollows of the baobabs, stacked like stolen fruit.",
                  "O Ensuhkeshdanna de Aratta adora uma charada: o que se esconde numa árvore mais larga do que alta? Babuínos, e as faíscas que eles guardam nos ocos dos baobás, empilhadas feito fruta roubada."),
                T("Reach the baobab woods", "Chegar ao bosque dos baobás"),
                T("Free the baboons that hoard the sparks", "Libertar os babuínos que guardam as faíscas"),
                T("The baobabs are empty and the sparks are up. Grandma Edna says the moon is past a half now, and that Jorge once lost a riddle in Aratta and paid for the milk for a month. Ensuhkeshdanna confirmed it, laughing, and gave us root boots for the mangrove.",
                  "Os baobás estão vazios e as faíscas subiram. A Vó Edna diz que a lua passou da metade, e que o Jorge uma vez perdeu uma charada em Aratta e pagou o leite por um mês. O Ensuhkeshdanna confirmou, rindo, e deu botas de raiz para o mangue."),
                T("The baboons hide high. Look up into the hollows.",
                  "Os babuínos se escondem no alto. Olhem para dentro dos ocos."),
                T("Joaquim! A duel of shoves later, I promise. First, six baboons in the baobab woods. They throw fruit. You have a shield. Ha!",
                  "Joaquim! Duelo de empurrão depois, prometo. Primeiro, seis babuínos no bosque dos baobás. Eles jogam fruta. Você tem escudo. Ha!"),
                T("Maria, a riddle: what grows when the fire passes? The baobab. And what grows when the light goes home? The moon. Six baboons, and help it grow.",
                  "Maria, uma charada: o que cresce quando o fogo passa? O baobá. E o que cresce quando a luz volta para casa? A lua. Seis babuínos, e ajuda ela a crescer."),
                T("Maithe, baboons always leave one on watch. Find the watcher first and the other five will come down by themselves.",
                  "Maithe, babuíno sempre deixa um de vigia. Acha o vigia primeiro que os outros cinco descem sozinhos."),
                T("Ícaro, a baobab holds a thousand jars of water, they say. These hold sparks. Count how many before you set them free, I have a bet with myself.",
                  "Ícaro, dizem que um baobá guarda mil jarras de água. Estes guardam faísca. Conta quantas antes de soltar, eu fiz uma aposta comigo mesmo."),
                T("Lavine, the baboons think nobody can climb as high as them. They have not met you. Six of them, and bring the riddle back with the answer.",
                  "Lavine, os babuínos acham que ninguém sobe tão alto quanto eles. Eles ainda não conhecem você. Seis deles, e traz a charada de volta com a resposta."));

            Step(all, "mid_story_r05_mangrove",
                T("Teeth in the Mangrove", "Dentes no Mangue"),
                T("Captain Liyongo won't sail while the mangrove crocodiles lie across the channel with sparks shining between their teeth. Further in, he says, Hedammu sleeps in the deep mangrove: let him sleep, the crocodiles are enough for today.",
                  "O Capitão Liyongo não zarpa enquanto os crocodilos do mangue ficam atravessados no canal, com faíscas brilhando entre os dentes. Mais para dentro, ele diz, o Hedammu dorme no mangue fundo: deixem ele dormir, os crocodilos já bastam por hoje."),
                T("Reach the shallow mangrove", "Chegar ao mangue raso"),
                T("Free the mangrove crocodiles that keep the sparks", "Libertar os crocodilos do mangue que guardam as faíscas"),
                T("The crocodiles opened their mouths and the light went up out of the mangrove like a flock. Grandma Edna says the moon over the Vila is fat enough to read by now. The rest of the light, Liyongo says, went inland with the rain, up the rivers to the delta of Jhilpur.",
                  "Os crocodilos abriram a boca e a luz subiu do mangue que nem um bando. A Vó Edna diz que a lua da Vila já está gorda o bastante para ler. O resto da luz, diz o Liyongo, foi terra adentro com a chuva, rio acima até o delta de Jhilpur."),
                T("They lie still like logs. Logs don't have eyes on top.",
                  "Eles ficam parados feito tronco. Tronco não tem olho em cima."),
                T("Joaquim, they say a guardian doesn't sink in the mangrove mud. Prove it. Six crocodiles in the shallows, and keep your feet on the roots.",
                  "Joaquim, dizem que guardião não afunda no lodo do mangue. Prova. Seis crocodilos no raso, e pisa nas raízes."),
                T("Maria, a healer aboard is worth two sails, and a healer in the mangrove is worth six crocodiles freed. Go, and we sail when you come back.",
                  "Maria, curandeira a bordo vale por duas velas, e curandeira no mangue vale seis crocodilos soltos. Vai, que a gente zarpa quando você voltar."),
                T("Maithe, crocodiles don't move until they do. Watch the bubbles. Six of them, and don't go past the shallows: Hedammu is past the shallows.",
                  "Maithe, crocodilo não se mexe até se mexer. Olha as bolhas. Seis deles, e não passa do raso: depois do raso é o Hedammu."),
                T("Ícaro, the crocodiles bite at a hundred pounds per square something. My navigator says so. Don't test it. Six of them, from a distance.",
                  "Ícaro, os crocodilos mordem com cem quilos por centímetro qualquer coisa. O meu navegador diz. Não testa. Seis deles, de longe."),
                T("Lavine, on my deck everybody learns to swim first. In the mangrove everybody learns to walk on roots. Six crocodiles, and you are captain of the root-walkers.",
                  "Lavine, no meu convés todo mundo aprende a nadar primeiro. No mangue todo mundo aprende a andar nas raízes. Seis crocodilos, e você é a capitã dos que andam nas raízes."));

            // ================= Região 6, Delta de Jhilpur =================
            Step(all, "mid_story_r06_rain",
                T("Coils in the Rain", "Anéis na Chuva"),
                T("Salmaios keeps the Mother Root of Jhilpur and listens to her every morning. She is thirsty for light. Up at the rain cascades, dimmed pythons coil around the falling water and squeeze the sparks out of the rain before they can rise.",
                  "O Salmaios cuida da Raiz-Mãe de Jhilpur e escuta ela toda manhã. Ela está com sede de luz. Lá nas cascatas da chuva, pítons apagadas se enrolam na água que cai e espremem as faíscas da chuva antes que elas subam."),
                T("Reach the rain cascades", "Chegar às cascatas da chuva"),
                T("Free the dimmed pythons coiled around the rain", "Libertar as pítons apagadas enroladas na chuva"),
                T("The pythons uncoiled and the rain fell light again. Grandma Edna says the moon rose orange last night, which Jorge said was the moon blushing. Salmaios gave us an antivenom amulet: the dead wood further south is worse.",
                  "As pítons desenrolaram e a chuva voltou a cair leve. A Vó Edna diz que a lua nasceu laranja ontem, que o Jorge dizia que era a lua envergonhada. O Salmaios deu um amuleto antiveneno: a mata morta, mais ao sul, é pior."),
                T("A coiled python is a knot. Untie the knot from the end.",
                  "Píton enrolada é nó. Desata o nó pela ponta."),
                T("Joaquim, the Mother Root drinks Living Water slowly, every day. Your water doesn't let things pass. Stand in the cascade and let nothing coil around you. Six pythons.",
                  "Joaquim, a Raiz-Mãe bebe Água Viva devagar, todo dia. A tua água não deixa passar. Fica na cascata e não deixa nada se enrolar em você. Seis pítons."),
                T("Maria, feel the bark: warm on the side the sun touches. The pythons are cold all over. Six of them at the cascades, and warm them back to themselves.",
                  "Maria, sente a casca: morna do lado onde o sol bate. As pítons estão frias inteiras. Seis delas nas cascatas, e esquenta elas de volta para elas mesmas."),
                T("Maithe, in the rain a python looks like a root and a root looks like a python. Your eye knows the difference. Six of them.",
                  "Maithe, na chuva píton parece raiz e raiz parece píton. O teu olho sabe a diferença. Seis delas."),
                T("Ícaro, the rain at the cascades falls slower than it should, because the coils hold it. If your numbers say so too, free six pythons and time the rain again.",
                  "Ícaro, a chuva nas cascatas cai mais devagar do que devia, porque os anéis seguram. Se os teus números disserem o mesmo, solta seis pítons e cronometra a chuva de novo."),
                T("Lavine, the Mother Root asked for you by the red ribbon. I don't know how she knows. Six pythons at the cascades, and she'll tell me the rest.",
                  "Lavine, a Raiz-Mãe pediu por você pela fita vermelha. Não sei como ela sabe. Seis pítons nas cascatas, e o resto ela me conta."));

            Step(all, "mid_story_r06_deadwood",
                T("The Dead Wood", "A Mata Morta"),
                T("Ramtha the Healer hums back at the wisps that buzz around the stilts of Tarchon. South of the stilts, in the dead wood near the Heart of the Mud, dimmed trolls stuff sparks into their pockets of bark. The Lodo-que-Engole lies further down; Ramtha says not today.",
                  "A Ramtha, a Curandeira, zumbe de volta para os fogos-fátuos que rondam as palafitas de Tarchon. Ao sul das palafitas, na mata morta perto do Coração do Lodo, trolls apagados enfiam faíscas nos bolsos de casca. O Lodo-que-Engole fica mais para baixo; a Ramtha diz que hoje não."),
                T("Reach the dead wood", "Chegar à mata morta"),
                T("Free the dimmed trolls that pocket the sparks", "Libertar os trolls apagados que embolsam as faíscas"),
                T("Five trolls, five pockets of light turned out. Grandma Edna says the moon is nearly round, missing only a sliver on one side, and the sliver points north. Ramtha says the cold up in the Teto do Mundo will bite, and gave us a thermal coat.",
                  "Cinco trolls, cinco bolsos de luz virados do avesso. A Vó Edna diz que a lua está quase redonda, faltando só uma fatia de um lado, e a fatia aponta para o norte. A Ramtha diz que o frio lá no Teto do Mundo morde, e deu uma roupa térmica."),
                T("The trolls are slow and they hit hard. Let them swing, then step in.",
                  "Os trolls são lentos e batem forte. Deixem eles balançarem e depois entrem."),
                T("Joaquim... you will not say if a troll hits you. Guardians never say. Say it to me after, and I'll close it by morning. Five trolls.",
                  "Joaquim... você não vai falar se um troll te acertar. Guardião nunca fala. Fala para mim depois, que eu fecho até amanhã. Cinco trolls."),
                T("Maria... my guardian lamp hums at the wisps. You hum too. In the dead wood, the trolls stopped hearing anything. Five of them... hum louder.",
                  "Maria... a minha lâmpada guardiã zumbe para os fogos-fátuos. Você também zumbe. Na mata morta, os trolls pararam de ouvir. Cinco deles... zumbe mais alto."),
                T("Maithe... in the dead wood every trunk is grey. The trolls are grey too. Count the ones that breathe. Five.",
                  "Maithe... na mata morta todo tronco é cinza. Os trolls também. Conta os que respiram. Cinco."),
                T("Ícaro... the bark pockets are sewn with mud. Mud from the Heart. Take a sample... from a distance... and free five trolls.",
                  "Ícaro... os bolsos de casca são costurados com lodo. Lodo do Coração. Pega uma amostra... de longe... e solta cinco trolls."),
                T("Lavine... the wisps followed you all the way from the stilts. They like you. Let them light the way through the dead wood. Five trolls.",
                  "Lavine... os fogos-fátuos te seguiram desde as palafitas. Eles gostam de você. Deixa eles iluminarem o caminho na mata morta. Cinco trolls."));

            // ================= Região 7, Teto do Mundo =================
            Step(all, "mid_story_r07_junipers",
                T("Bears in the Junipers", "Ursos nos Zimbros"),
                T("At Sangkent, Abā rides the chutes down the terraces and shouts every time. He has stopped shouting: on the juniper slope above the chutes, brown bears sleep on piles of sparks like honey, and the slope has gone dark.",
                  "Em Sangkent, o Abā desce as calhas dos terraços gritando toda vez. Ele parou de gritar: na encosta dos zimbros, acima das calhas, ursos-pardos dormem em cima de montes de faísca como se fosse mel, e a encosta escureceu."),
                T("Reach the juniper slope", "Chegar à encosta dos zimbros"),
                T("Free the brown bears that sleep on the sparks", "Libertar os ursos-pardos que dormem em cima das faíscas"),
                T("The bears woke up as bears and wandered off to look for real honey. Grandma Edna says she heard Abā shouting from the chutes all the way on the radio. She says the last sliver of moon is still missing, and Baraies knows these mountains better than anyone. Abā gave us climbing hooks.",
                  "Os ursos acordaram ursos e foram procurar mel de verdade. A Vó Edna diz que ouviu o Abā gritando nas calhas pelo rádio. Diz que a última fatia da lua ainda falta, e que o Baraies conhece essas montanhas melhor do que ninguém. O Abā deu grampos de escalada."),
                T("A sleeping bear wakes grumpy. Wake them one at a time.",
                  "Urso dormindo acorda bravo. Acordem um de cada vez."),
                T("Joaquim, a guardian afraid of a cart? Then a guardian afraid of a bear? No. Six bears on the junipers, and then the chute, and you shout.",
                  "Joaquim, guardião com medo de carrinho? Então guardião com medo de urso? Não. Seis ursos nos zimbros, depois a calha, e você grita."),
                T("Maria, at dusk the terraces light one by one. Lately the seventh stays dark. The light it needs is under the bears. Six of them.",
                  "Maria, no fim da tarde os terraços acendem um por um. Ultimamente o sétimo fica apagado. A luz que ele precisa está debaixo dos ursos. Seis deles."),
                T("Maithe, bears sleep downwind of the chutes. Come at them from above, with the wind in your face. Six, and then you can ride the chute and pretend you didn't like it.",
                  "Maithe, os ursos dormem do lado de baixo do vento das calhas. Chega por cima, com o vento na cara. Seis, e depois você pode descer a calha e fingir que não gostou."),
                T("Ícaro, I need a brake for the chutes, and you need six bears off the junipers. Trade? You first. Then the brake.",
                  "Ícaro, eu preciso de um freio para as calhas, e você precisa de seis ursos fora dos zimbros. Troca? Você primeiro. Depois o freio."),
                T("Lavine, the bears are big and you are not, and that is exactly why you can walk between them without waking them. Six bears. Ribbons on the cart are yours after.",
                  "Lavine, os ursos são grandes e você não, e é justamente por isso que você passa entre eles sem acordar. Seis ursos. As fitas do carrinho são tuas depois."));

            Step(all, "mid_story_r07_peaks",
                T("The Fifth Valley", "O Quinto Vale"),
                T("Baraies the Teacher says that from the fort you see four valleys, and the fifth is behind the light. Up on the ice peaks the almas, the wild ones of the snow, have gathered the last sparks of the mountains into a cairn, and the fifth valley has gone dark.",
                  "O Baraies, o Professor, diz que do forte se veem quatro vales, e o quinto fica atrás da luz. Lá nos picos gelados, os almas, os bravos da neve, juntaram as últimas faíscas das montanhas num monte de pedras, e o quinto vale escureceu."),
                T("Reach the icy peaks", "Chegar aos picos gelados"),
                T("Free the almas that pile up the sparks", "Libertar os almas que empilham as faíscas"),
                T("From the top of the cairn you can see the fifth valley, and past it, east, a plain with nine rings of walls: Mingcheng. The last sparks are running there along the canals, Baraies says, and something keeps them from reaching the moon. Grandma Edna said she would keep the tea warm all the way to the plain. Aydahar sleeps in the pass: we went round.",
                  "Do alto do monte de pedras dá para ver o quinto vale, e depois dele, a leste, uma planície com nove anéis de muralha: Mingcheng. As últimas faíscas correm para lá pelos canais, diz o Baraies, e alguma coisa impede que elas cheguem à lua. A Vó Edna disse que ia deixar o chá quente até a planície. O Aydahar dorme no passo: a gente deu a volta."),
                T("The almas throw snow and stones. Keep moving and keep together.",
                  "Os almas jogam neve e pedra. Continuem andando e fiquem juntos."),
                T("Joaquim, a map is a promise. This one promises ice, wind and five almas at the peaks. Keep its promise, and it will keep you warm.",
                  "Joaquim, um mapa é uma promessa. Este promete gelo, vento e cinco almas nos picos. Cumpre a promessa dele, que ele cuida de você."),
                T("Maria, every student asks where the fifth valley is. You never asked, you just looked at the light. That is the answer. Five almas, and it opens.",
                  "Maria, todo aluno pergunta onde fica o quinto vale. Você nunca perguntou, só olhou para a luz. Essa é a resposta. Cinco almas, e ele abre."),
                T("Maithe, up on the peaks the wind is honest, for once. Listen to it. Five almas, and look east from the cairn: that is your next lesson.",
                  "Maithe, lá nos picos o vento é honesto, para variar. Escuta ele. Cinco almas, e olha para o leste do monte de pedras: essa é a tua próxima lição."),
                T("Ícaro, measure the cairn before you scatter it. Height, width, sparks per stone. Then free five almas. I'll grade it.",
                  "Ícaro, mede o monte de pedras antes de espalhar. Altura, largura, faíscas por pedra. Depois solta cinco almas. Eu dou nota."),
                T("Lavine, the almas are shy, not bad. They took the sparks because they were cold. Five of them, and tell them the sun comes back.",
                  "Lavine, os almas são tímidos, não maus. Pegaram as faíscas porque estavam com frio. Cinco deles, e diz para eles que o sol volta."));

            // ================= Região 8, Planície de Mingcheng =================
            Step(all, "mid_story_r08_lions",
                T("The Spirit Way", "O Caminho dos Espíritos"),
                T("Bögü of the Ring Guard stands still and sees everything. What he sees now: the stone lions of the spirit way, which should let the light pass to the city, turned their heads around and bite every spark that comes down from the mountains.",
                  "O Bögü, da Guarda dos Anéis, fica parado e vê tudo. O que ele vê agora: os leões de pedra do caminho dos espíritos, que deviam deixar a luz passar para a cidade, viraram a cabeça e mordem toda faísca que desce das montanhas."),
                T("Reach the way of the lions", "Chegar ao caminho dos leões"),
                T("Free the stone lions that bite the sparks", "Libertar os leões de pedra que mordem as faíscas"),
                T("The lions turned their heads back and the light ran down the spirit way into the rings. Grandma Edna says she could hear the drum of the Ring Guard over the radio, and that Jorge once tried to march with it and fell into a canal. Bögü gave us a sun seal for the gates.",
                  "Os leões viraram a cabeça de volta e a luz desceu pelo caminho dos espíritos até os anéis. A Vó Edna diz que ouviu o tambor da Guarda dos Anéis pelo rádio, e que o Jorge uma vez tentou marchar junto e caiu num canal. O Bögü deu um selo do sol para os portões."),
                T("The lions look one way. Come at them from the other.",
                  "Os leões olham para um lado. Cheguem pelo outro."),
                T("Joaquim, the Ring Guard would take you tomorrow. Today, take six lions off the spirit way, and stand still while they come at you. You are good at that.",
                  "Joaquim, a Guarda dos Anéis te aceitava amanhã. Hoje, tira seis leões do caminho dos espíritos e fica parado enquanto eles vêm. Você é bom nisso."),
                T("Maria, nine rings, nine gates each, one drum. When the drum stops, the light should pass. The lions stop it. Six of them, and the drum can play again.",
                  "Maria, nove anéis, nove portões cada, um tambor. Quando o tambor para, a luz devia passar. Os leões não deixam. Seis deles, e o tambor pode tocar de novo."),
                T("Maithe, the lions are in pairs, and one of each pair is looking at you. Six lions. Shoot the one that isn't.",
                  "Maithe, os leões ficam em pares, e um de cada par está olhando para você. Seis leões. Atira no que não está."),
                T("Ícaro, the lions were carved to guard. Someone turned them around, carefully, with tools. Find out who later. Now, six lions.",
                  "Ícaro, os leões foram esculpidos para guardar. Alguém virou eles, com cuidado, com ferramenta. Descobre quem depois. Agora, seis leões."),
                T("Lavine, the Ring Guard does not take children. It would take you. Don't tell anyone I said so. Six lions on the spirit way.",
                  "Lavine, a Guarda dos Anéis não aceita criança. Você ela aceitava. Não conta para ninguém que eu disse. Seis leões no caminho dos espíritos."));

            Step(all, "mid_story_r08_lock",
                T("The Moon Lock", "A Eclusa da Lua"),
                T("Lin Deng, Master of the Canal, opens the four locks in order so the low quarters breathe. The fourth, the Moon Lock on the canal of lanterns, will not open: stone turtles have settled into the gates, and the light that should flow out to the moon is dammed behind them.",
                  "O Lin Deng, Mestre do Canal, abre as quatro eclusas em ordem para os bairros baixos respirarem. A quarta, a Eclusa da Lua no canal das lanternas, não abre: tartarugas de pedra se acomodaram nos portões, e a luz que devia correr até a lua está represada atrás delas."),
                T("Reach the Moon Lock", "Chegar à Eclusa da Lua"),
                T("Free the stone turtles that jam the lock", "Libertar as tartarugas de pedra que travam a eclusa"),
                T("The lock opened and the water went down shining, as if the moon itself had been poured into the canal. Grandma Edna says the moon over the Vila is almost full, and her voice went quiet. Lin Deng gave us a runic lamp and said the last of it is under the city, in the terracotta pits.",
                  "A eclusa abriu e a água desceu brilhando, como se a própria lua tivesse sido derramada no canal. A Vó Edna diz que a lua da Vila está quase cheia, e a voz dela ficou baixinha. O Lin Deng deu uma lamparina rúnica e disse que o último pedaço está debaixo da cidade, nos fossos de terracota."),
                T("The turtles don't move. Move them.", "As tartarugas não se mexem. Mexam elas."),
                T("Joaquim, the canal is like you: calm on top, strong underneath. Push five turtles out of my lock and you will see the water thank you.",
                  "Joaquim, o canal é que nem você: calmo em cima, forte embaixo. Empurra cinco tartarugas para fora da minha eclusa e você vai ver a água agradecer."),
                T("Maria, four locks, four levels. Open them in order and the low quarters breathe. The fourth is the moon's. Five turtles, and then the order is complete.",
                  "Maria, quatro eclusas, quatro níveis. Abre em ordem e os bairros baixos respiram. A quarta é da lua. Cinco tartarugas, e aí a ordem se completa."),
                T("Maithe, five turtles in the gates, each one slower than the last. Your arrows will bounce off the shells. Aim at the legs.",
                  "Maithe, cinco tartarugas nos portões, cada uma mais lenta que a outra. As tuas flechas vão quicar no casco. Mira nas pernas."),
                T("Ícaro, a lock is a machine that thinks in water. Mine stopped thinking. Five turtles out of the gates, and then help me count the levels.",
                  "Ícaro, eclusa é uma máquina que pensa com água. A minha parou de pensar. Cinco tartarugas fora dos portões, e depois me ajuda a contar os níveis."),
                T("Lavine, the turtles are very old and very stubborn. So am I. You are young and more stubborn than both of us. Five turtles at the Moon Lock.",
                  "Lavine, as tartarugas são muito velhas e muito teimosas. Eu também. Você é nova e mais teimosa que nós dois. Cinco tartarugas na Eclusa da Lua."));

            Step(all, "mid_story_r08_full_moon",
                T("The Full Moon", "A Lua Cheia"),
                T("Fuduodan the Reader brought a book over the mountains on a camel, and in it the Moon fills with light and pours it into the Sun, who carries it home. The last caught sparks are in the terracotta pits under Mingcheng, held by soldiers of clay who forgot they were made to guard the light, not to keep it.",
                  "O Fuduodan, o Leitor, trouxe um livro pelas montanhas num camelo, e nele a Lua se enche de luz e derrama no Sol, que leva tudo para casa. As últimas faíscas presas estão nos fossos de terracota debaixo de Mingcheng, nas mãos de soldados de barro que esqueceram que foram feitos para guardar a luz, não para ficar com ela."),
                T("Reach the terracotta pits", "Chegar aos fossos de terracota"),
                T("Free the terracotta soldiers that keep the last sparks", "Libertar os soldados de terracota que guardam as últimas faíscas"),
                T("The moon is full. Grandma Edna said it on the radio and then said nothing for a long time. When she spoke again, she said the moonlight fell on the Caderno on the bench, right on the lining, and the lining has stitches she didn't sew. Grandpa Jorge's stitches. She'll open it when we're all home, or at least all on the radio.",
                  "A lua está cheia. A Vó Edna disse pelo rádio e depois ficou um tempão sem falar. Quando falou de novo, contou que a luz da lua caiu no Caderno, em cima do banco, bem no forro, e que o forro tem uma costura que não é dela. A costura do Vô Jorge. Ela vai abrir quando todo mundo estiver em casa, ou pelo menos no rádio."),
                T("Clay remembers its shape. Remind the soldiers of theirs.",
                  "Barro lembra a forma que tem. Lembrem os soldados da deles."),
                T("Joaquim, two principles: the Light and the Dark. You don't need the book to know which one you guard. Six soldiers in the pits, and the moon fills.",
                  "Joaquim, dois princípios: a Luz e a Escuridão. Você não precisa do livro para saber qual dos dois você guarda. Seis soldados nos fossos, e a lua enche."),
                T("Maria, in the book the light goes home in two ships, the Moon and then the Sun. You heard the call first. Six soldiers, and the Moon Ship sails full.",
                  "Maria, no livro a luz volta para casa em duas barcas, a da Lua e depois a do Sol. Você ouviu o chamado primeiro. Seis soldados, e a Barca da Lua navega cheia."),
                T("Maithe, the soldiers stand in rows, and rows are easy to count and hard to break. Six of them. Count your cousins on the way out, as you always do.",
                  "Maithe, os soldados ficam em fileiras, e fileira é fácil de contar e difícil de quebrar. Seis deles. Conta os primos na saída, como você sempre faz."),
                T("Ícaro, you would have brought my book in a notebook, with diagrams. Bring me a diagram of the pits after you free six soldiers. I'll put it in the back of the book.",
                  "Ícaro, você teria trazido o meu livro num caderno, com diagramas. Me traz um diagrama dos fossos depois de soltar seis soldados. Eu ponho no fim do livro."),
                T("Lavine, the book says the moon is a ship. Your cousins tell me you say it's Kaggen's shoe. The book doesn't say you're wrong. Six soldiers, and fill the shoe.",
                  "Lavine, o livro diz que a lua é uma barca. Os teus primos me contaram que você diz que é o sapato do Kaggen. O livro não diz que você está errada. Seis soldados, e enche o sapato."));

            // ================= Linhas da cadeia =================
            all.Add(new LocalizationEntry(MidStoryCatalog.TooLowKeyBase + "joaquim", "Joaquim, not yet. Out there the beasts are hungrier than you, and that's saying something. Eat, train, come back.",
                "Joaquim, ainda não. Lá fora os bichos estão com mais fome que você, e isso é dizer muito. Come, treina e volta."));
            all.Add(new LocalizationEntry(MidStoryCatalog.TooLowKeyBase + "maria", "Maria, the moon will wait for you. It's been waiting a long time and it knows how. Go with light and come back stronger.",
                "Maria, a lua espera você. Ela já espera há muito tempo e sabe esperar. Vai com luz e volta mais forte."));
            all.Add(new LocalizationEntry(MidStoryCatalog.TooLowKeyBase + "maithe", "Maithe, you'd get there. Your cousins wouldn't, not yet. Bring them all up first, then come back to me.",
                "Maithe, você chegava lá. Os teus primos não, ainda não. Sobe todo mundo primeiro e depois volta aqui."));
            all.Add(new LocalizationEntry(MidStoryCatalog.TooLowKeyBase + "icaro", "Ícaro, check your numbers again. The road ahead is stronger than you are, for now. A few more levels and the sums come out right.",
                "Ícaro, confere os teus números de novo. A estrada da frente está mais forte que você, por enquanto. Mais uns níveis e a conta fecha."));
            all.Add(new LocalizationEntry(MidStoryCatalog.TooLowKeyBase + "lavine", "Lavine, it isn't your age, it's the road. It is harder than you are ready for today. Tomorrow is another thing.",
                "Lavine, não é a tua idade, é a estrada. Ela está mais difícil do que você está pronta hoje. Amanhã é outra coisa."));
        }
    }
}
